import{_ as e,o as t,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Arriving and visas","description":"The main ways to enter Qatar, what to carry at the border, and how to check a visa on the Ministry of Interior site.","frontmatter":{"title":"Arriving and visas","description":"The main ways to enter Qatar, what to carry at the border, and how to check a visa on the Ministry of Interior site.","lastChecked":"2026-10","sourceCount":10},"headers":[],"relativePath":"guide/arriving-and-visas.md","filePath":"guide/arriving-and-visas.md"}'),i={name:"guide/arriving-and-visas.md"};function s(n,a,f,l,c,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="arriving-and-visas" tabindex="-1">Arriving and visas <a class="header-anchor" href="#arriving-and-visas" aria-label="Permalink to &quot;Arriving and visas&quot;">​</a></h1><p>How you enter Qatar depends on your nationality and your reason for coming. Visitors may get a visa on arrival or apply online through Hayya, while people moving here come in on a residence visa and finish their residency steps after landing.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup><sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><p>The Ministry of Interior (MOI) says visitor visa rules can change without notice, so check the rules for your nationality close to your travel date.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="ways-to-enter" tabindex="-1">Ways to enter <a class="header-anchor" href="#ways-to-enter" aria-label="Permalink to &quot;Ways to enter&quot;">​</a></h2><h3 id="visa-on-arrival-or-no-visa-in-advance" tabindex="-1">Visa on arrival or no visa in advance <a class="header-anchor" href="#visa-on-arrival-or-no-visa-in-advance" aria-label="Permalink to &quot;Visa on arrival or no visa in advance&quot;">​</a></h3><ul><li>MOI says citizens of more than 95 countries can enter with a visa on arrival at Qatar&#39;s entry points, and that citizens of several countries are exempt from getting a visa beforehand.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>The length of stay varies by nationality.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup> MOI&#39;s on-arrival page lists tourist categories of 90 days and 30 days, along with other categories such as a visa for GCC residents and a business visa with its own terms.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li><li>GCC nationals do not need a visa. Hayya says your passport or GCC ID is enough.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li></ul><h3 id="hayya-e-visas" tabindex="-1">Hayya e-visas <a class="header-anchor" href="#hayya-e-visas" aria-label="Permalink to &quot;Hayya e-visas&quot;">​</a></h3><ul><li>Hayya is the online platform for tourist visas. MOI lists four entry permits on it: the tourist visa, the entry visa for residents of GCC countries, the entry visa for people accompanying GCC citizens, and entry by Electronic Travel Authorization (ETA).<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>You apply at hayya.qa or through the Hayya mobile app.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup><sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup></li></ul><h3 id="visas-issued-in-advance" tabindex="-1">Visas issued in advance <a class="header-anchor" href="#visas-issued-in-advance" aria-label="Permalink to &quot;Visas issued in advance&quot;">​</a></h3><ul><li>These are visas you receive before you travel and present at the arrival port. MOI&#39;s list includes business visas and family (personal visit) visas, which have their own page: <a href="./family-visas">Family visas</a>.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li></ul><h3 id="coming-to-live-or-work" tabindex="-1">Coming to live or work <a class="header-anchor" href="#coming-to-live-or-work" aria-label="Permalink to &quot;Coming to live or work&quot;">​</a></h3><ul><li>MOI&#39;s Work Visa on Company Sponsorship is for workers being brought to ministries, government bodies, semi-government organizations and private companies.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li><li>MOI lists these conditions: attested educational certificates, an employment contract between you and the employer, a good conduct certificate from your home country attested by the Qatar Embassy there, and passing the medical test outside Qatar.<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6]</a></sup></li><li>If you enter on a residence visa, you must do the medical checkup within thirty days of entering. Fingerprints come after the medical, and then the residency procedures are completed. The <a href="./residence-permit-and-qid">Residence permit and QID</a> page has the details.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li></ul><h2 id="what-to-have-ready-at-the-border" tabindex="-1">What to have ready at the border <a class="header-anchor" href="#what-to-have-ready-at-the-border" aria-label="Permalink to &quot;What to have ready at the border&quot;">​</a></h2><ul><li>A valid passport. The two MOI pages differ on how long it must stay valid: the visit visas page says at least three months, and the visa conditions page says not less than 6 months.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup><sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup> Having six months or more meets both.<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7]</a></sup></li><li>A confirmed return ticket or a confirmed ticket to continue your journey.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>Valid health insurance from a company registered with the Ministry of Public Health.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li><li>For some nationalities, a hotel reservation, cash or a credit card.<sup class="footnote-ref"><a href="#fn7" id="fnref7:2">[7]</a></sup></li><li>If you are driving in, vehicle insurance. Visitors using the Abu Samra border complete the required policies electronically and can pre-register through Hayya.<sup class="footnote-ref"><a href="#fn1" id="fnref1:9">[1]</a></sup></li></ul><h2 id="how-to-check-a-visa" tabindex="-1">How to check a visa <a class="header-anchor" href="#how-to-check-a-visa" aria-label="Permalink to &quot;How to check a visa&quot;">​</a></h2><ul><li>MOI&#39;s Visa Services page lets you follow the approval of a work or visit visa with the application number, or look it up with the visa number, and print the details of an issued visa.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></li><li>The same page has a Track Application Status option for the Qatar Visa Center.<sup class="footnote-ref"><a href="#fn8" id="fnref8:1">[8]</a></sup></li><li>For a Hayya e-visa, use Track your E-Visa with your entry reference number, or your passport number and nationality.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></li></ul><h2 id="staying-longer-and-overstaying" tabindex="-1">Staying longer and overstaying <a class="header-anchor" href="#staying-longer-and-overstaying" aria-label="Permalink to &quot;Staying longer and overstaying&quot;">​</a></h2><ul><li>Confirm how long your visit visa allows when you enter. MOI says a family visit gives you one month.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li>To stay longer on a family visit, finish the medical checkup before your allowed period ends and apply for an extension.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li><li>If the visa runs out without an extension, MOI charges a fine for each day of delay, up to a maximum. The amounts are on the MOI tips page.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></li><li>The Visa Services page also has a Visa Extension / Fine Payment option.<sup class="footnote-ref"><a href="#fn8" id="fnref8:2">[8]</a></sup></li><li>You can look up overstay violations through the Overstay Violations Inquiry service.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup></li></ul><p>See also: <a href="./residence-permit-and-qid">Residence permit and QID</a>, <a href="./family-visas">Family visas</a>, <a href="./metrash">Metrash</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/qatarvisas/" target="_blank" rel="noreferrer">Qatar Visit Visas</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:9" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/47" target="_blank" rel="noreferrer">Tips &amp; Guidelines</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/c27493" target="_blank" rel="noreferrer">On-arrival visas</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Hayya, <a href="https://hayya.qa/en" target="_blank" rel="noreferrer">Hayya Portal</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/c29604" target="_blank" rel="noreferrer">Visas in advance</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fwork%2Bentry%2Fqr%25240" target="_blank" rel="noreferrer">Work Visa on Company Sponsorship</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/768" target="_blank" rel="noreferrer">Visa Conditions</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref7:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn8" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/visaservices" target="_blank" rel="noreferrer">Visa Services</a>. Last checked: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn9" class="footnote-item"><p>Hayya, <a href="https://hayya.qa/en/visa-inquiry" target="_blank" rel="noreferrer">Track your E-Visa</a>. Last checked: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn10" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/overstay" target="_blank" rel="noreferrer">Search and Follow up</a>. Last checked: 2026-10. <a href="#fnref10" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',22)])])}const u=e(i,[["render",s]]);export{p as __pageData,u as default};
